    }

    /** `GET /auth/native/authorize` */
    public suspend fun authNativeAuthorize(provider: String? = null, codeChallenge: String? = null, codeChallengeMethod: String? = null, redirectUri: String? = null, state: String? = null): WebAuthNativeAuthorizeResult {
        val query = buildMap<String, String> {
            provider?.let { put("provider", it) }
            codeChallenge?.let { put("code_challenge", it) }
            codeChallengeMethod?.let { put("code_challenge_method", it) }
            redirectUri?.let { put("redirect_uri", it) }
            state?.let { put("state", it) }
        }
        val response = caller.send(RESTRequest("GET", "/auth/native/authorize", query))
        return when (response.status) {
            200 -> WebAuthNativeAuthorizeResult.Ok(response.text(200))
